    /* 日干が剋される・陰陽同 */
    '車騎星は、迷いを置かずまっすぐ動いて場を先へ進める動き方を指します。誰も手をつけていない用件を最初に引き受ける場面や、締め切りが目の前に迫った時期に、勢いがそのまま働きになりそうです。逆に、根回しを重ねて全員の同意を待つ進め方では、待つあいだに気持ちが萎えやすいようです。動き出す前に一度だけ行き先を確かめる手順を挟むほうが、勢いが空回りしにくいと見ます。',
    /* 日干が剋される・陰陽異 */
