    /* 日干が生じられる・陰陽同 */
    '龍高星は、知らない場所へ出ていって学びを持ち帰る動き方を指します。行ったことのない土地での仕事や、勝手の違う相手と組む場面で、身につくものが増えていきそうです。逆に、同じ道順を同じ時刻に繰り返すだけの時期が長引くと、気持ちが外へ向いて手元が留守になりやすいようです。年に何度か外へ出る予定を先に入れておくほうが、日々の場も保ちやすいと見ます。',
